package com.trainflow.program; import jakarta.persistence.*; import java.time.Instant; import java.util.*; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="training_programs") public class TrainingProgram {@Id @JdbcTypeCode(SqlTypes.VARCHAR) @Column(columnDefinition="char(36)") private UUID id;@JdbcTypeCode(SqlTypes.VARCHAR) @Column(name="training_case_id",nullable=false,unique=true,columnDefinition="char(36)") private UUID trainingCaseId;@Column(nullable=false,length=250) private String title;@Column(name="general_objectives",columnDefinition="text") private String generalObjectives;@Column(columnDefinition="text") private String prerequisites;@Column(name="evaluation_method",columnDefinition="text") private String evaluationMethod;@Column(name="is_submitted",nullable=false) private boolean submitted;@Column(name="submitted_at")private Instant submittedAt;@Column(name="is_validated",nullable=false)private boolean validated;@Column(name="validated_at")private Instant validatedAt;@Column(name="returned_at")private Instant returnedAt;@Column(name="return_reason",columnDefinition="text")private String returnReason;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@OneToMany(mappedBy="program",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("position asc")private List<TrainingProgramDay> days=new ArrayList<>();protected TrainingProgram(){}public TrainingProgram(UUID c,String t){id=UUID.randomUUID();trainingCaseId=c;title=t;}@PrePersist void insert(){var n=Instant.now();if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTrainingCaseId(){return trainingCaseId;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getGeneralObjectives(){return generalObjectives;}public void setGeneralObjectives(String v){generalObjectives=v;}public String getPrerequisites(){return prerequisites;}public void setPrerequisites(String v){prerequisites=v;}public String getEvaluationMethod(){return evaluationMethod;}public void setEvaluationMethod(String v){evaluationMethod=v;}public boolean isSubmitted(){return submitted;}public void setSubmitted(boolean v){submitted=v;}public Instant getSubmittedAt(){return submittedAt;}public void setSubmittedAt(Instant v){submittedAt=v;}public boolean isValidated(){return validated;}public void setValidated(boolean v){validated=v;}public Instant getValidatedAt(){return validatedAt;}public void setValidatedAt(Instant v){validatedAt=v;}public Instant getReturnedAt(){return returnedAt;}public void setReturnedAt(Instant v){returnedAt=v;}public String getReturnReason(){return returnReason;}public void setReturnReason(String v){returnReason=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public List<TrainingProgramDay> getDays(){return days;}}
